(\forall yA)[x:=u]=
\begin{cases}
\forall yA,&y=x,\\
\forall y(A[x:=u]),&y\ne x\land y\notin\operatorname{FVN_T}(u),\\
\forall z((A[y:=z])[x:=u]),&y\ne x\land y\in\operatorname{FVN_T}(u),
\end{cases}

(\forall ZA)[X:=Y]=
\begin{cases}
\forall ZA,&Z=X,\\
\forall Z(A[X:=Y]),&Z\ne X\land Z\ne Y,\\
\forall W((A[Z:=W])[X:=Y]),&Z\ne X\land Z=Y,
\end{cases}
